      codeName: 'toolbar_drbar_ability_toolbar_deuiaction1_click',
      fullCodeName: 'master_toolbar_drbar_ability_toolbar_deuiaction1_click',
      scriptCode:
        "const drbar = view.getCtrl('DRBAR', 'drbar');\r\nif (drbar) {\r\n    const { selectedItem, drBarItems } = drbar.state;\r\n    let index = drBarItems.findIndex(x => x.tag === selectedItem);\r\n    index += 1;\r\n    if (index > drBarItems.length - 1) {\r\n        index -= drBarItems.length;\r\n    }\r\n    const tag = drBarItems[index].tag;\r\n    drbar.setActive(tag);\r\n}\r\nconst tips = '切换分页成功';\r\nibiz.message.info(tips);\r\nconsole.log(tips);",
      timeout: 60000,
      uiactionMode: 'CUSTOM',
      uiactionTag: 'toolbar_drbar_ability_toolbar_deuiaction1_click',
      uiactionType: 'DEUIACTION',
      showBusyIndicator: true,
