      scriptCode:
        "const drtab = view.getCtrl('DRTAB', 'tabexppanel');\r\nif (drtab) {\r\n    const { activeName, drTabPages } = drtab.state;\r\n    let index = drTabPages.findIndex(x => x.tag === activeName);\r\n    index += 1;\r\n    if (index > drTabPages.length - 1) {\r\n        index -= drTabPages.length;\r\n    }\r\n    const tag = drTabPages[index].tag;\r\n    drtab.setActive(tag);\r\n}\r\nconst tips = '切换分页成功';\r\nibiz.message.info(tips);\r\nconsole.log(tips);",
