        'master_toolbar_tabexppanel_ability_toolbar_deuiaction1_click',
      scriptCode:
        "const tabexppanel = view.getCtrl('TABEXPPANEL', 'tabexppanel');\r\nif (tabexppanel) {\r\n    const { activeName, tabPages } = tabexppanel.state;\r\n    let index = tabPages.findIndex(x => x.tabTag === activeName);\r\n    index += 1;\r\n    if (index > tabPages.length - 1) {\r\n        index -= tabPages.length;\r\n    }\r\n    const tabTag = tabPages[index].tabTag;\r\n    tabexppanel.setActive(tabTag);\r\n}\r\nconst tips = '切换分页成功';\r\nibiz.message.info(tips);\r\nconsole.log(tips);",
